package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.*;import net.minecraft.client.particle.*;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.util.Mth;import net.minecraft.world.phys.*;import java.util.*;
/** One event, fixed global budgets. No gameplay randomness, server fragments, scans or damage. */
public final class Hg01Fx{
 public static final int MAX_EFFECTS=8,MAX_PARTICLES=192;private static final ArrayList<Particle> particles=new ArrayList<>();private static final ArrayDeque<Long> effects=new ArrayDeque<>();private static ClientLevel world;private static long events;
 public static void tick(){var next=Minecraft.getInstance().level;if(next!=world){for(var p:particles)p.remove();particles.clear();effects.clear();Hg01ItemRenderer.clear();world=next;}particles.removeIf(p->!p.isAlive());if(world!=null)while(!effects.isEmpty()&&effects.peekFirst()<=world.getGameTime())effects.removeFirst();}
 public static void receive(ExplosionVfxMessage m){tick();if(m.intensity()<=0)return;if(world==null||!world.dimension().location().equals(m.dimension()))return;var mc=Minecraft.getInstance();double distance=mc.gameRenderer.getMainCamera().getPosition().distanceTo(new Vec3(m.x(),m.y(),m.z()));if(distance>160||effects.size()>=MAX_EFFECTS||particles.size()>=MAX_PARTICLES)return;float detail=distance<40?1:distance<80?.6f:.3f;var quality=mc.options.particles().get();if(quality==ParticleStatus.DECREASED)detail*=.6;if(quality==ParticleStatus.MINIMAL)detail*=.3;detail*=RubbleClientConfig.DETAIL.get().floatValue();float strength=(float)Math.sqrt(m.intensity());var rng=new Random(m.seed());effects.addLast(world.getGameTime()+Hg01Config.SMOKE_LIFE.get()+30);events++;
  int count=RubbleClientConfig.SMOKE.get()?Math.max(4,(int)(56*detail*Hg01Config.SMOKE.get())):0;for(int i=0;i<count;i++){var sprites=ExplosionVfxClient.hgSprite(1);if(sprites==null)break;double a=rng.nextDouble()*Math.PI*2,r=rng.nextDouble()*1.25;add(new Smoke(world,m.x()+Math.cos(a)*r,m.y()+rng.nextDouble()*.35,m.z()+Math.sin(a)*r,Math.cos(a)*(.012+rng.nextDouble()*.022),.014+rng.nextDouble()*.015,Math.sin(a)*(.012+rng.nextDouble()*.022),(float)(1.4+rng.nextDouble()*.9)*(quality==ParticleStatus.MINIMAL?1.3f:1)*strength,Hg01Config.SMOKE_LIFE.get(),i<4?0:rng.nextInt(18),sprites,rng.nextFloat()*6.28f,(rng.nextFloat()-.5f)*.012f));}
  for(int i=0;i<(RubbleClientConfig.SHARDS.get()?Math.max(5,(int)(28*detail)):0);i++){double a=rng.nextDouble()*Math.PI*2,h=.18+rng.nextDouble()*.65;add(new Hg01ShardParticle(world,m.x(),m.y()+.12,m.z(),Math.cos(a)*h,.12+rng.nextDouble()*.6,Math.sin(a)*h,(float)(i%3==0?.04+rng.nextDouble()*.04:.09+rng.nextDouble()*.1),rng.nextInt(25)+28,rng.nextFloat()*6.28f));}
  var fire=ExplosionVfxClient.hgSprite(0);if(fire!=null)for(int i=0;i<2;i++)add(new Smoke(world,m.x(),m.y()+.15,m.z(),0,0,0,strength*(i==0?1.35f:.65f),i==0?3:8,0,fire,0,0));
 }
 private static void add(Particle p){if(particles.size()>=MAX_PARTICLES){p.remove();return;}if(!RubbleVisualBudget.claim(p))return;particles.add(p);Minecraft.getInstance().particleEngine.add(p);}
 public static String diagnostics(){return "events="+events+",effects="+effects.size()+",particles="+particles.size();}
 private static final class Smoke extends TextureSheetParticle{
  final float size,spin;final int delay;final boolean fire;final SpriteSet frames;
  Smoke(ClientLevel l,double x,double y,double z,double vx,double vy,double vz,float s,int life,int delay,SpriteSet frames,float angle,float spin){super(l,x,y,z);this.size=s;this.lifetime=life+delay;this.delay=delay;this.frames=frames;this.spin=spin;fire=life<=8;hasPhysics=false;xd=vx;yd=vy;zd=vz;roll=oRoll=angle;quadSize=s*.25f;alpha=0;setSpriteFromAge(frames);rCol=gCol=bCol=fire?1:.075f;}
  @Override public void tick(){xo=x;yo=y;zo=z;oRoll=roll;if(++age>=lifetime){remove();return;}if(age<delay)return;float t=(age-delay)/(float)(lifetime-delay);float rise=1-(float)Math.exp(-(age-delay)/12f);x+=xd;z+=zd;y+=yd*rise;roll+=spin;quadSize=size*(fire?1:.3f+1.15f*(float)(1-Math.exp(-(age-delay)/22f)));alpha=fire?.95f*(1-t):.88f*Mth.clamp((age-delay)/4f,0,1)*Mth.clamp((1-t)/.48f,0,1);if(!fire)rCol=gCol=bCol=.065f+.13f*t;setSpriteFromAge(frames);}
  public ParticleRenderType getRenderType(){return ParticleRenderType.PARTICLE_SHEET_TRANSLUCENT;}public int getLightColor(float p){return fire?0xF000F0:super.getLightColor(p);}
 }
 private Hg01Fx(){}
}
